import java.util.*;import java.util.concurrent.*;
class Account implements Comparable<Account>{private final String number,name;private long balance;Account(String n,String name,long b){number=n;this.name=name;balance=b;}String getNumber(){return number;}long getBalance(){return balance;}String getName(){return name;}void deposit(long a){if(a>0)balance+=a;}boolean withdraw(long a){if(a>0&&a<=balance){balance-=a;return true;}return false;}public int compareTo(Account a){return number.compareTo(a.number);}public String toString(){return number+" | "+name+" | Balance: "+balance;}}
public class Main {public static void main(String[] args){Map<String,Account> accounts=new HashMap<>();Account a=new Account("AC0001","Aarav Shah",5000),b=new Account("AC0002","Diya Patel",2000),c=new Account("AC0003","Rohan Mehta",9000);for(Account x:List.of(a,b,c))accounts.put(x.getNumber(),x);System.out.println("LOOKUP AC0002: "+accounts.get("AC0002"));List<Account> sorted=new ArrayList<>(accounts.values());sorted.sort(Comparator.comparingLong(Account::getBalance).reversed().thenComparing(Account::getNumber));System.out.println("BY BALANCE:");sorted.forEach(System.out::println);System.out.println("BY ACCOUNT NUMBER:");Collections.sort(sorted);sorted.forEach(System.out::println);System.out.println("ABOVE 4000:");sorted.stream().filter(x->x.getBalance()>4000).forEach(System.out::println);ConcurrentHashMap<String,Account> shared=new ConcurrentHashMap<>(accounts);synchronized(a){a.withdraw(300);}System.out.println("Thread-safe store count: "+shared.size());}}
